class Solution { public:
 vector<int> findIndices(vector<int>& nums,int indexDifference,int valueDifference){
  int n=nums.size(),lo=0,hi=0;
  for(int j=indexDifference;j<n;++j){int i=j-indexDifference;
   if(nums[i]<nums[lo])lo=i;if(nums[i]>nums[hi])hi=i;
   if(abs(nums[j]-nums[lo])>=valueDifference)return {lo,j};
   if(abs(nums[j]-nums[hi])>=valueDifference)return {hi,j};
  }return {-1,-1};
 }
};
